def run(inputs, params):
    # A question is a hit@k when its source document is among the top k chunks.
    top = inputs["in1"]
    expected = list(inputs["in2"])
    hit1 = sum(row[0] == want for row, want in zip(top, expected))
    hit3 = sum(want in list(row)[:3] for row, want in zip(top, expected))
    report = f"hit@1 {hit1}/{len(expected)}, hit@3 {hit3}/{len(expected)}"
    for k in (1, 3):
        missed = [str(i + 1) for i, (row, want) in enumerate(zip(top, expected)) if want not in list(row)[:k]]
        if missed:
            report += f"; missed at {k}: question " + ", ".join(missed)
    return {"out1": hit1 / len(expected), "out2": hit3 / len(expected), "out3": report}
